import sys

def patch_file(path, replacements):
    with open(path, "r", encoding="utf-8") as f:
        content = f.read()
    applied = 0
    skipped = 0
    for label, old, new in replacements:
        if new in content:
            print(f"ALREADY APPLIED [{path} :: {label}] -- skipping.")
            skipped += 1
            continue
        if old not in content:
            print(f"MISSING ANCHOR [{path} :: {label}] -- aborting, no changes written to {path}.")
            sys.exit(1)
        content = content.replace(old, new, 1)
        applied += 1
    if applied:
        with open(path, "w", encoding="utf-8") as f:
            f.write(content)
    print(f"{path}: {applied} edit(s) applied, {skipped} already present.")

